-- ===== Postcondition checks =====
DO $$
DECLARE
  bad_count integer;
BEGIN
  SELECT count(*) INTO bad_count FROM translation_segments WHERE surah_number IN (2,36) AND alignment_status = 'unresolved';
  IF bad_count <> 0 THEN RAISE EXCEPTION 'Postcondition failed: % segments still unresolved in surah 2/36', bad_count; END IF;

  SELECT count(DISTINCT ayah_number) INTO bad_count FROM translation_segment_ayahs WHERE surah_number = 2;
  IF bad_count <> 286 THEN RAISE EXCEPTION 'Postcondition failed: surah 2 covers % distinct ayahs, expected 286', bad_count; END IF;

  SELECT count(DISTINCT ayah_number) INTO bad_count FROM translation_segment_ayahs WHERE surah_number = 36;
  IF bad_count <> 83 THEN RAISE EXCEPTION 'Postcondition failed: surah 36 covers % distinct ayahs, expected 83', bad_count; END IF;

  SELECT count(*) INTO bad_count FROM (SELECT surah_number, source_ordinal, count(*) c FROM translation_segments WHERE surah_number IN (2,36) GROUP BY 1,2 HAVING count(*) > 1) x;
  IF bad_count <> 0 THEN RAISE EXCEPTION 'Postcondition failed: % duplicate source_ordinal rows', bad_count; END IF;

  RAISE NOTICE 'Phase 4 correction postconditions PASSED';
END $$;

COMMIT;